import {choice, fields, text} from '../../../../shared/src/index.js';
import {parseLocation, routeLink} from '../../router.js';

const keys = ['orgId', 'q', 'visibility', 'teamId', 'owned', 'cursor'];
function viewText(value, field, max) {
  if (typeof value === 'string' && /[\u0000-\u001f\u007f]/.test(value)) throw new Error('Invalid saved-filter ' + field);
  return text(value ?? '', field, {min: 0, max, trim: field !== 'cursor'});
}
export function filterView(input = {}) {
  fields(input, keys);
  const view = {
    orgId: viewText(input.orgId, 'orgId', 100),
    q: viewText(input.q, 'q', 100),
    visibility: choice(input.visibility, 'visibility', ['all', 'personal', 'team'], 'all'),
    teamId: viewText(input.teamId, 'teamId', 100),
    owned: choice(input.owned, 'owned', ['true', 'false'], 'false'),
    cursor: viewText(input.cursor, 'cursor', 4000)
  };
  if (view.cursor && !/^[A-Za-z0-9_-]+$/.test(view.cursor)) throw new Error('Invalid saved-filter cursor');
  if (!view.orgId && (view.teamId || view.cursor)) throw new Error('A saved-filter team or page needs an organization');
  return view;
}
export function filterViewLocation(input = {}) {
  const view = filterView(input);
  return routeLink('/filters', {
    orgId: view.orgId, q: view.q, visibility: view.visibility === 'all' ? '' : view.visibility,
    teamId: view.teamId, owned: view.owned === 'false' ? '' : view.owned, cursor: view.cursor
  }).slice(1);
}
export function filterReturnLocation(value, orgId = '') {
  if (value === undefined) return filterViewLocation({orgId});
  if (typeof value !== 'string' || value.includes('#') || /%(?![\da-f]{2})/i.test(value)) throw new Error('Invalid saved-filter return view');
  const location = parseLocation(value);
  if (location.pathname !== '/filters') throw new Error('Return view must be a saved-filter list');
  const search = value.includes('?') ? value.slice(value.indexOf('?') + 1) : '';
  try {decodeURIComponent(search);} catch {throw new Error('Malformed saved-filter return encoding');}
  const parameters = new URLSearchParams(search);
  if ([...parameters.keys()].length !== new Set(parameters.keys()).size) throw new Error('Duplicate saved-filter return field');
  return filterViewLocation(location.query);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

async function browser(mode) {
  const server = await testServer();
  let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', {name: 'View Browser', email: 'filter-view@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'Saved view organization'})).data.organization;
    const team = (await api('POST', '/orgs/' + org.id + '/teams', {name: 'Saved view team'})).data.team;
    await api('POST', '/teams/' + team.id + '/members', {userId: auth.data.user.id});
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'VIEW', name: 'Saved view project'})).data.project;
    await api('POST', '/projects/' + project.id + '/issues', {title: 'Current run target', priority: 3});
    for (let i = 0; i < 30; i++) {
      const created = await api('POST', '/filters', {orgId: org.id, name: 'View item ' + String(i).padStart(2, '0'), description: 'needle lookup', query: 'priority>=3', visibility: 'team', teamId: team.id});
      assert.equal(created.status, 201);
    }
    const other = (await api('POST', '/filters', {orgId: org.id, name: 'Background personal filter', query: ''})).data.filter;
    const settings = {url: server.url, cookie: auth.cookie, orgId: org.id, teamId: team.id, otherId: other.id, mode};
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./filter-view-browser.py', import.meta.url)), JSON.stringify(settings)], {detached: true});
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {try {process.kill(-child.pid, 'SIGKILL');} catch {} reject(new Error('Saved-filter view browser exceeded bounded deadline'));}, 30000);
      child.stdout.on('data', value => stdout += value); child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {clearTimeout(timer); resolve({code, stdout, stderr});});
    });
    if (result.stderr) console.error(result.stderr);
    assert.equal(result.code, 0, result.stderr);
    const proof = JSON.parse(result.stdout.trim());
    assert.equal(proof.ok, true); assert.equal(proof.mode, mode);
    console.error(JSON.stringify({filterViewBrowserProof: proof}));
  } finally {if (child?.pid) {try {process.kill(-child.pid, 'SIGKILL');} catch {}} await server.close();}
}
test('actual Chromium applied saved-filter URLs restore later pages reload and native Back Forward', {timeout: 35000}, () => browser('view'));
test('actual Chromium detail run edit copy return to selected view and reject unsafe return targets', {timeout: 35000}, () => browser('return'));
test('actual Chromium view dirty decisions and delayed listing editor save custody', {timeout: 35000}, () => browser('custody'));
